#include "../common.h"
int main(void){char s[500],p[500];int a=9,b=4,c=5,d=7,det=modn(a*d-b*c,26),iv=invn(det,26);if(iv<0){puts("Key is not invertible.");return 1;}printf("Plaintext: ");fgets(s,sizeof s,stdin);int n=0;for(int i=0;s[i];i++)if(isalpha((unsigned char)s[i]))p[n++]=toupper(s[i]);if(n%2)p[n++]='X';p[n]=0;char ct[500];for(int i=0;i<n;i+=2){int x=p[i]-'A',y=p[i+1]-'A';ct[i]='A'+modn(a*x+b*y,26);ct[i+1]='A'+modn(c*x+d*y,26);}ct[n]=0;printf("Ciphertext: %s\n",ct);int ia=modn(d*iv,26),ib=modn(-b*iv,26),ic=modn(-c*iv,26),id=modn(a*iv,26);printf("Inverse matrix mod 26: [%d %d; %d %d]\n",ia,ib,ic,id);printf("Decrypted: ");for(int i=0;i<n;i+=2){int x=ct[i]-'A',y=ct[i+1]-'A';putchar('A'+modn(ia*x+ib*y,26));putchar('A'+modn(ic*x+id*y,26));}puts("");return 0;}